components.css:
.ds-anchor { display: flex; align-items: center; justify-content: space-between; gap: 1.4rem; padding: 0.85rem 1.05rem; background: var(--red, #a7362a); color: var(--paper, #e8e1d0); border-radius: 0; box-shadow: 0 3px 0 var(--red-deep, #6f231a), 0 18px 30px rgb(0 0 0 / 0.26); font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.65rem; letter-spacing: 0.12em; text-transform: uppercase; text-decoration: none; transition: transform 0.22s ease, background 0.22s ease; }
.ds-anchor:hover { background: var(--red-bright, #bd4436); transform: translateY(-2px); }
.ds-anchor:active { transform: translateY(1px); }
.ds-anchor:focus-visible { outline: 2px solid var(--red-bright, #bd4436); outline-offset: 3px; }

.ds-sound { display: inline-flex; align-items: center; gap: 0.6rem; min-height: 1.9rem; padding: 0.35rem 0.6rem; border: 1px solid var(--line-strong, rgb(232 225 208 / 0.3)); border-radius: 0; background: rgb(8 10 7 / 0.28); color: rgb(232 225 208 / 0.72); font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.12em; text-transform: uppercase; cursor: pointer; transition: color 0.2s ease, border-color 0.2s ease, background 0.2s ease; }
.ds-sound:hover { color: var(--paper, #e8e1d0); border-color: rgb(232 225 208 / 0.55); }
.ds-sound[aria-pressed="true"] { color: var(--paper, #e8e1d0); border-color: rgb(167 54 42 / 0.75); background: rgb(167 54 42 / 0.14); }
.ds-sound:focus-visible { outline: 2px solid var(--red-bright, #bd4436); outline-offset: 3px; }
.ds-sound__label span { color: #cf6a5b; }
.ds-sound__bars { display: inline-flex; align-items: flex-end; gap: 2px; height: 12px; }
.ds-sound__bars i { display: block; width: 2px; height: 4px; background: currentColor; opacity: 0.65; transform-origin: bottom; }
.ds-sound__bars i:nth-child(2) { height: 8px; }
.ds-sound__bars i:nth-child(3) { height: 6px; }
.ds-sound__bars.is-playing i { animation: ds-meter 1.1s ease-in-out infinite; }
.ds-sound__bars.is-playing i:nth-child(2) { animation-delay: 0.18s; }
.ds-sound__bars.is-playing i:nth-child(3) { animation-delay: 0.36s; }
@keyframes ds-meter { 0%, 100% { transform: scaleY(0.45); } 50% { transform: scaleY(1); } }

.ds-index { display: flex; flex-direction: column; width: 9.5rem; gap: 0.9rem; color: var(--paper, #e8e1d0); font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); }
.ds-index__label { padding-bottom: 0.55rem; border-bottom: 1px solid var(--line, rgb(232 225 208 / 0.16)); color: rgb(232 225 208 / 0.62); font-size: 0.56rem; letter-spacing: 0.32em; text-transform: uppercase; }
.ds-index__list { display: grid; gap: 0.1rem; margin: 0; padding: 0; list-style: none; }
.ds-index__link { display: flex; align-items: center; gap: 0.6rem; padding: 0.32rem 0; color: rgb(232 225 208 / 0.58); font-size: 0.62rem; letter-spacing: 0.1em; text-transform: uppercase; text-decoration: none; transition: color 0.22s ease, transform 0.22s ease; }
.ds-index__tick { display: block; width: 14px; height: 1px; background: currentColor; opacity: 0.5; transition: width 0.25s ease, background 0.25s ease, opacity 0.25s ease; }
.ds-index__link:hover { color: var(--paper, #e8e1d0); transform: translateX(2px); }
.ds-index__link:hover .ds-index__tick { width: 24px; }
.ds-index__link[aria-current="location"] { color: var(--paper, #e8e1d0); }
.ds-index__link[aria-current="location"] .ds-index__tick { width: 30px; background: var(--red, #a7362a); opacity: 1; }
.ds-index__link:focus-visible { outline: 2px solid var(--red-bright, #bd4436); outline-offset: 3px; }
.ds-index__foot { padding-top: 0.6rem; border-top: 1px solid var(--line, rgb(232 225 208 / 0.16)); color: rgb(232 225 208 / 0.6); font-size: 0.56rem; letter-spacing: 0.08em; line-height: 1.5; text-transform: uppercase; }

.ds-file-wrap { padding-top: 1.6rem; }
.ds-file { position: relative; background: var(--stock-file-01, #e2dac7); color: var(--paper-ink, #1a1c16); border-radius: 0; box-shadow: 0 26px 62px rgb(0 0 0 / 0.46), 0 6px 18px rgb(0 0 0 / 0.3); }
.ds-file__tab { position: absolute; top: -1.5rem; left: 1.2rem; display: inline-block; padding: 0.38rem 0.8rem; background: var(--manila-tab, #b59a62); color: #2b271d; border-radius: 0; box-shadow: 0 5px 12px rgb(0 0 0 / 0.22); font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.13em; text-transform: uppercase; }
.ds-file__summary { display: block; padding: clamp(1.8rem, 3.4vw, 2.9rem) clamp(1.3rem, 4vw, 3.2rem) clamp(1.1rem, 2.4vw, 1.7rem); cursor: pointer; list-style: none; }
.ds-file__summary::-webkit-details-marker { display: none; }
.ds-file__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 0.55rem; padding-bottom: 0.6rem; border-bottom: 1px solid rgb(26 28 22 / 0.26); }
.ds-file__title { color: #171912; font-family: var(--font-display, 'Helvetica Condensed', 'Archivo Narrow', sans-serif); font-size: clamp(2.6rem, 5vw, 4.2rem); font-weight: 700; letter-spacing: -0.02em; line-height: 0.84; text-transform: uppercase; }
.ds-file__filing { display: flex; flex-direction: column; align-items: flex-end; gap: 0.2rem; color: #444636; font-family: var(--font-tech, 'Kairos Sans', 'Rajdhani', sans-serif); font-size: 0.56rem; letter-spacing: 0.1em; line-height: 1.3; text-transform: uppercase; white-space: nowrap; }
.ds-file__filing span:first-child { color: var(--red-ink, #7f231b); font-weight: 600; }
.ds-file__subtitle { display: block; margin-bottom: 0.8rem; color: #474838; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.58rem; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-file__abstract { display: block; max-width: 68ch; color: #333529; font-size: 0.92rem; line-height: 1.64; }
.ds-file__cue { display: flex; align-items: center; gap: 0.5rem; margin-top: 1.25rem; color: #474838; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-file__plus { position: relative; display: inline-grid; place-items: center; width: 1.35rem; height: 1.35rem; border: 1px solid rgb(26 28 22 / 0.38); }
.ds-file__plus::before, .ds-file__plus::after { content: ""; position: absolute; background: var(--red, #a7362a); }
.ds-file__plus::before { width: 9px; height: 1px; }
.ds-file__plus::after { width: 1px; height: 9px; }
.ds-file[data-open="true"] .ds-file__plus { transform: rotate(45deg); }
.ds-file__plus { transition: transform 0.28s ease; }
.ds-file__summary:focus-visible { outline: 2px solid var(--red-bright, #bd4436); outline-offset: -2px; }

.ds-plate { margin: 0; padding: 0.45rem; border: 1px solid rgb(26 28 22 / 0.3); border-radius: 0; background: var(--carbon-frame, #0d0f0b); transform: rotate(-0.35deg); }
.ds-plate__img { display: block; width: 100%; height: auto; }
.ds-plate__cap { display: flex; flex-wrap: wrap; gap: 0.4rem 0.55rem; padding: 0.5rem 0.25rem 0.1rem; color: #c2bdaa; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.04em; line-height: 1.45; }
.ds-plate__cap span { color: #e0a094; text-transform: uppercase; }

.ds-kit { padding: clamp(1.2rem, 3vw, 2rem); background: var(--stock-kit, #d3d4bf); color: var(--paper-ink, #1a1c16); border-radius: 0; box-shadow: 0 30px 70px rgb(0 0 0 / 0.46), 0 8px 22px rgb(0 0 0 / 0.3); transform: rotate(-0.35deg); }
.ds-kit__caption { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
.ds-kit__table { width: 100%; border-collapse: collapse; font-size: 0.78rem; line-height: 1.5; }
.ds-kit__table thead th { padding: 0.4rem 0.6rem 0.6rem; border-bottom: 1px solid rgb(26 28 22 / 0.4); color: #575a48; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; font-weight: 400; letter-spacing: 0.16em; text-align: left; text-transform: uppercase; }
.ds-kit__table tbody th { width: 17%; padding: 0.85rem 0.6rem; border-bottom: 1px solid rgb(26 28 22 / 0.18); color: #1f2119; font-family: var(--font-tech, 'Kairos Sans', 'Rajdhani', sans-serif); font-size: 0.62rem; font-weight: 600; letter-spacing: 0.1em; text-align: left; text-transform: uppercase; vertical-align: top; }
.ds-kit__table tbody td { padding: 0.85rem 0.6rem; border-bottom: 1px solid rgb(26 28 22 / 0.18); color: #333528; vertical-align: top; }
.ds-kit__table tbody td:last-child { color: #3b3d2f; font-family: var(--font-tech, 'Kairos Sans', 'Rajdhani', sans-serif); font-size: 0.6rem; letter-spacing: 0.06em; text-transform: uppercase; }
.ds-kit__table tbody tr:hover { background: rgb(255 255 255 / 0.18); }

.ds-channel { display: grid; grid-template-columns: 4.6rem minmax(0, 1fr) auto; gap: 0.8rem; align-items: baseline; padding: 1rem 0.15rem; border-bottom: 1px solid var(--line, rgb(232 225 208 / 0.16)); color: rgb(232 225 208 / 0.72); text-decoration: none; transition: color 0.2s ease, padding-left 0.2s ease; }
.ds-channel:hover { padding-left: 0.5rem; color: var(--paper, #e8e1d0); }
.ds-channel:focus-visible { outline: 2px solid var(--red-bright, #bd4436); outline-offset: 3px; }
.ds-channel__label { color: rgb(232 225 208 / 0.6); font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-channel__value { font-size: 0.8rem; overflow-wrap: anywhere; }
.ds-channel__arrow { color: var(--red, #a7362a); display: inline-flex; }

.ds-sheet { padding: clamp(1.4rem, 2.5vw, 2.2rem) clamp(1.4rem, 2.8vw, 2.6rem); background: var(--paper, #e8e1d0); color: var(--paper-ink, #1a1c16); border-radius: 0; box-shadow: 0 40px 90px rgb(0 0 0 / 0.56), 0 10px 32px rgb(0 0 0 / 0.4); transform: rotate(-1.1deg); }
.ds-sheet__fileline { display: flex; justify-content: space-between; gap: 1rem; padding-bottom: 0.65rem; border-bottom: 1px solid rgb(26 28 22 / 0.28); color: #3f4237; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-sheet__name { margin: 1.05rem 0 0.55rem; color: #14160f; font-family: var(--font-display, 'Helvetica Condensed', 'Archivo Narrow', sans-serif); font-size: clamp(2.6rem, 6vw, 4rem); font-weight: 700; letter-spacing: -0.025em; line-height: 0.83; text-transform: uppercase; }
.ds-sheet__role { margin: 0; color: #4d4f42; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.62rem; letter-spacing: 0.17em; text-transform: uppercase; }
.ds-sheet__role span { color: var(--red, #a7362a); }
.ds-sheet__note { max-width: 44ch; margin: 1.15rem 0 0; color: #393b30; font-size: 0.91rem; line-height: 1.66; }
.ds-sheet__meta { display: flex; flex-wrap: wrap; gap: 0.45rem 1.2rem; margin-top: 0.9rem; padding-top: 0.7rem; border-top: 1px solid rgb(26 28 22 / 0.2); color: #5b5b4c; font-family: var(--font-type, 'ITC American Typewriter', 'Courier Prime', monospace); font-size: 0.56rem; letter-spacing: 0.08em; text-transform: uppercase; }
